import { encryptCompactJwe, decryptCompactJwe } from 'micro509/jose';
import { unwrap } from 'micro509/result';
const descriptor = { kind: 'rsa', scheme: 'oaep', hash: 'SHA-512' };
const pair = await generateKeyPair(descriptor);
const publicKey = unwrap(await importSpkiPem(await pair.exportSpkiPem(), descriptor));
const privateKey = unwrap(await importPrivateKeyPem(await pair.exportPkcs8Pem(), descriptor));
const plaintext = new TextEncoder().encode(JSON.stringify({ state: 'café 🦊' }));
const token = unwrap(await encryptCompactJwe({
    publicKey,
    plaintext,
    algorithm: 'RSA-OAEP-512',
    encryption: 'A256GCM',
    header: { typ: 'state+jwe', kid: 'state-1' },
}));
const decrypted = unwrap(await decryptCompactJwe(token, {
    privateKey,
    keyManagementAlgorithms: ['RSA-OAEP-512'],
    contentEncryptionAlgorithms: ['A256GCM'],
}));
if (new TextDecoder().decode(decrypted.plaintext) !==
    new TextDecoder().decode(plaintext)) {
    throw new Error('plaintext mismatch');
}
console.log('Compact JWE:', token);
console.log('Decrypted bytes:', new TextDecoder().decode(decrypted.plaintext));
